// Front-end API code generated from the back end's OpenAPI schema
// (Foundation Fixes fix 2). Run `npm run generate:api` after
// `python tools/export_openapi.py`; never edit lib/generated by hand.
import {defineConfig} from '@hey-api/openapi-ts';

export default defineConfig({
  input: './openapi.json',
  output: {path: './lib/generated', postProcess: ['prettier']},
  plugins: [
    '@hey-api/client-fetch',
    '@hey-api/typescript',
    // The app uses Zod 3 (package.json); checked 2026-10-01 that the plugin
    // supports it via compatibilityVersion. The database keeps UTC times
    // without an offset (backend app/core/time.py), so those must pass too.
    {name: 'zod', compatibilityVersion: 3, dates: {local: true, offset: true}},
    {name: '@hey-api/sdk', validator: true},
    '@tanstack/react-query',
  ],
});
